import React from 'react';

/**
 * IntelliPrep logo, animated.
 *
 * The mark (person, "P" ribbon, graduation cap, sparkle) and the wordmark are
 * taken from the official logo, so this is the exact same artwork. Intro
 * sequence (about 2.4s): head pops, the "i" grows, the "P" ribbon unfurls, the
 * cap drops in, the sparkle spins up and the letters rise. After that it idles
 * (floating mark, swinging tassel, twinkling sparkle).
 *
 *   variant="full"  mark + "IntelliPrep" wordmark
 *   variant="mark"  mark only (inline loaders)
 *
 * Size it with a width class, e.g. className="w-64". Height follows the artwork.
 * prefers-reduced-motion shows the finished logo with no movement.
 */
const CSS = `.ipl-svg{overflow:visible;display:block}
.ipl-float{animation:ipl-float 3.4s ease-in-out 2.6s infinite alternate}
.ipl-head{animation:ipl-pop .65s cubic-bezier(.3,1.4,.5,1) .1s both}
.ipl-i{animation:ipl-grow .85s cubic-bezier(.3,1.3,.5,1) .3s both}
.ipl-p{animation:ipl-unfurl .95s cubic-bezier(.25,1.1,.4,1) .6s both}
.ipl-cap{animation:ipl-drop 1s cubic-bezier(.3,0,.4,1) 1.05s both,ipl-nod 4.2s ease-in-out 2.6s infinite}
.ipl-tassel{animation:ipl-swing 2.6s ease-in-out 2.2s infinite}
.ipl-spark{animation:ipl-sparkin .7s cubic-bezier(.3,1.5,.5,1) 1.5s both,ipl-twinkle 2.2s ease-in-out 2.4s infinite}
.ipl-word path{animation:ipl-rise .6s cubic-bezier(.2,.9,.3,1) both}
.ipl-word path:nth-child(1){animation-delay:1.00s}
.ipl-word path:nth-child(2){animation-delay:1.07s}
.ipl-word path:nth-child(3){animation-delay:1.14s}
.ipl-word path:nth-child(4){animation-delay:1.21s}
.ipl-word path:nth-child(5){animation-delay:1.28s}
.ipl-word path:nth-child(6){animation-delay:1.35s}
.ipl-word path:nth-child(7){animation-delay:1.42s}
.ipl-word path:nth-child(8){animation-delay:1.49s}
.ipl-word path:nth-child(9){animation-delay:1.56s}
.ipl-word path:nth-child(10){animation-delay:1.63s}
.ipl-word path:nth-child(11){animation-delay:1.70s}

@keyframes ipl-pop{0%{transform:scale(0);opacity:0}100%{transform:scale(1);opacity:1}}
@keyframes ipl-grow{0%{transform:scaleY(0)}100%{transform:scaleY(1)}}
@keyframes ipl-unfurl{0%{transform:scaleX(0);opacity:0}15%{opacity:1}100%{transform:scaleX(1);opacity:1}}
@keyframes ipl-drop{0%{transform:translateY(-110px) rotate(-20deg);opacity:0}45%{transform:translateY(10px) rotate(5deg);opacity:1}70%{transform:translateY(-4px) rotate(-2deg)}100%{transform:translateY(0) rotate(0);opacity:1}}
@keyframes ipl-nod{0%,100%{transform:rotate(0)}50%{transform:rotate(-1.6deg)}}
@keyframes ipl-swing{0%,100%{transform:rotate(0)}25%{transform:rotate(9deg)}75%{transform:rotate(-9deg)}}
@keyframes ipl-sparkin{0%{transform:scale(0) rotate(-140deg);opacity:0}100%{transform:scale(1) rotate(0);opacity:1}}
@keyframes ipl-twinkle{0%,100%{transform:scale(1) rotate(0);opacity:1}50%{transform:scale(1.35) rotate(18deg);opacity:.7}}
@keyframes ipl-rise{0%{transform:translateY(34px);opacity:0}100%{transform:translateY(0);opacity:1}}
@keyframes ipl-float{0%{transform:translateY(0)}100%{transform:translateY(-7px)}}
@media (prefers-reduced-motion:reduce){.ipl-svg *{animation:none!important}}`;

