export default function AnimatedLogo({ variant = 'full', className = '', title = 'IntelliPrep' }) {
  const full = variant === 'full';
  return (
    <svg
      className={`ipl-svg ${className}`}
      viewBox={full ? '0 0 980 830' : '136 6 664 600'}
      role="img"
      aria-label={title}
      xmlns="http://www.w3.org/2000/svg"
    >
      <title>{title}</title>
      <style>{CSS}</style>
      {MARK}
      {full && WORD}
    </svg>
  );
}
